import { encodeFrame, ProtocolLimits, SafeCsvPacket } from './safeCsvEngine';

export function generateCsvProtocolHeader(limits: ProtocolLimits): string {
  return `/**
 * CsvProtocol.h
 * ESP32 · Arduino framework · FreeRTOS · C++
 *
 * Flexible fixed-header + variable KEY=VALUE sensor telemetry protocol.
 * Supports CRC-16/CCITT-FALSE integrity, 16-bit sequence rollover,
 * 32-packet replay window, Session ID reboot detection, and multi-UART routing.
 *
 * Generated by SafeCsv Studio
 */

#ifndef CSV_PROTOCOL_H
#define CSV_PROTOCOL_H

#include <Arduino.h>
#include <HardwareSerial.h>
#include <freertos/FreeRTOS.h>
#include <freertos/queue.h>
#include <freertos/semphr.h>
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

/* ============================================================================
 * Compile-Time Configuration Macros (override before #include "CsvProtocol.h")
 * ============================================================================ */

#ifndef SAFECSV_PROTOCOL_VERSION
#define SAFECSV_PROTOCOL_VERSION 1
#endif

#ifndef SAFECSV_MAX_FIELDS
#define SAFECSV_MAX_FIELDS ${limits.maxFields}
#endif

#ifndef SAFECSV_MAX_KEY_LEN
#define SAFECSV_MAX_KEY_LEN ${limits.maxKeyLen}
#endif

#ifndef SAFECSV_MAX_VAL_LEN
#define SAFECSV_MAX_VAL_LEN ${limits.maxValLen}
#endif

#ifndef SAFECSV_MAX_FRAME_LEN
#define SAFECSV_MAX_FRAME_LEN ${limits.maxFrameLen}
#endif

#ifndef SAFECSV_TX_QUEUE_DEPTH
#define SAFECSV_TX_QUEUE_DEPTH ${limits.txQueueDepth}
#endif

#ifndef SAFECSV_FRAME_TIMEOUT_MS
#define SAFECSV_FRAME_TIMEOUT_MS ${limits.frameTimeoutMs}UL
#endif

#ifndef SAFECSV_MAX_NODE_ID
#define SAFECSV_MAX_NODE_ID ${limits.maxNodeId}
#endif

/* Standard Node IDs */
#define SAFECSV_NODE_ALL       0
#define SAFECSV_NODE_PRIMARY   1
#define SAFECSV_NODE_SECONDARY 2
#define SAFECSV_NODE_THIRD     3

/* Standard Packet Types */
#define SAFECSV_TYPE_STATUS    'S'
#define SAFECSV_TYPE_CONTROL   'C'
#define SAFECSV_TYPE_ACK       'A'
#define SAFECSV_TYPE_HEARTBEAT 'H'

/* ============================================================================
 * CRC-16/CCITT-FALSE (Poly: 0x1021, Init: 0xFFFF, No Reflect, No Final XOR)
 * ============================================================================ */
inline uint16_t safeCsvCrc16CcittFalse(const char* data, size_t len) {
    uint16_t crc = 0xFFFF;
    for (size_t i = 0; i < len; ++i) {
        crc ^= (uint16_t)((uint8_t)data[i]) << 8;
        for (uint8_t bit = 0; bit < 8; ++bit) {
            if (crc & 0x8000) {
                crc = (uint16_t)((crc << 1) ^ 0x1021);
            } else {
                crc = (uint16_t)(crc << 1);
            }
        }
    }
    return crc;
}

inline bool safeCsvIsReservedChar(char c) {
    return (c == ',' || c == '=' || c == '*' || c == '<' || c == '>' || c == '\\r' || c == '\\n');
}

inline bool safeCsvHasReservedChars(const char* s) {
    if (!s) return true;
    for (size_t i = 0; s[i] != '\\0'; ++i) {
        if (safeCsvIsReservedChar(s[i])) return true;
    }
    return false;
}

/* ============================================================================
 * Variable Payload Field & Packet Container
 * ============================================================================ */
struct SafeCsvField {
    char key[SAFECSV_MAX_KEY_LEN + 1];
    char value[SAFECSV_MAX_VAL_LEN + 1];
};

struct SafeCsvPacket {
    uint8_t  version;
    uint8_t  sourceId;
    uint8_t  destinationId;
    char     type;
    uint16_t sequence;
    uint64_t timestamp;
    uint8_t  ttl;
    uint8_t  fieldCount;
    SafeCsvField fields[SAFECSV_MAX_FIELDS];

    SafeCsvPacket() {
        clear();
    }

    void clear() {
        version       = SAFECSV_PROTOCOL_VERSION;
        sourceId      = 0;
        destinationId = SAFECSV_NODE_ALL;
        type          = SAFECSV_TYPE_STATUS;
        sequence      = 0;
        timestamp     = 0ULL;
        ttl           = 3;
        fieldCount    = 0;
        memset(fields, 0, sizeof(fields));
    }

    bool addField(const char* key, const char* value) {
        if (!key || !value || key[0] == '\\0') return false;
        if (strlen(key) > SAFECSV_MAX_KEY_LEN) return false;
        if (strlen(value) > SAFECSV_MAX_VAL_LEN) return false;
        if (safeCsvHasReservedChars(key) || safeCsvHasReservedChars(value)) return false;

        /* Update existing key if already present */
        for (uint8_t i = 0; i < fieldCount; ++i) {
            if (strcmp(fields[i].key, key) == 0) {
                strncpy(fields[i].value, value, SAFECSV_MAX_VAL_LEN);
                fields[i].value[SAFECSV_MAX_VAL_LEN] = '\\0';
                return true;
            }
        }

        if (fieldCount >= SAFECSV_MAX_FIELDS) return false;
        strncpy(fields[fieldCount].key, key, SAFECSV_MAX_KEY_LEN);
        fields[fieldCount].key[SAFECSV_MAX_KEY_LEN] = '\\0';
        strncpy(fields[fieldCount].value, value, SAFECSV_MAX_VAL_LEN);
        fields[fieldCount].value[SAFECSV_MAX_VAL_LEN] = '\\0';
        fieldCount++;
        return true;
    }

    bool addFloat(const char* key, float val, uint8_t decimals = 1) {
        char buf[SAFECSV_MAX_VAL_LEN + 1];
        snprintf(buf, sizeof(buf), "%.*f", decimals, (double)val);
        return addField(key, buf);
    }

    bool addInt(const char* key, int32_t val) {
        char buf[SAFECSV_MAX_VAL_LEN + 1];
        snprintf(buf, sizeof(buf), "%ld", (long)val);
        return addField(key, buf);
    }

    const char* getString(const char* key) const {
        if (!key) return nullptr;
        for (uint8_t i = 0; i < fieldCount; ++i) {
            if (strcmp(fields[i].key, key) == 0) {
                return fields[i].value;
            }
        }
        return nullptr;
    }

    bool getFloat(const char* key, float& outVal) const {
        const char* raw = getString(key);
        if (!raw) return false;
        char* endPtr = nullptr;
        float parsed = strtof(raw, &endPtr);
        if (endPtr == raw || *endPtr != '\\0') return false;
        outVal = parsed;
        return true;
    }

    bool getInt(const char* key, int32_t& outVal) const {
        const char* raw = getString(key);
        if (!raw) return false;
        char* endPtr = nullptr;
        long parsed = strtol(raw, &endPtr, 10);
        if (endPtr == raw || *endPtr != '\\0') return false;
        outVal = (int32_t)parsed;
        return true;
    }

    bool getUint64(const char* key, uint64_t& outVal) const {
        const char* raw = getString(key);
        if (!raw) return false;
        char* endPtr = nullptr;
        unsigned long long parsed = strtoull(raw, &endPtr, 10);
        if (endPtr == raw || *endPtr != '\\0') return false;
        outVal = (uint64_t)parsed;
        return true;
    }

    bool encodeFrame(char* outBuf, size_t outBufSize, size_t& outLen) const {
        if (!outBuf || outBufSize < 32) return false;
        if (sourceId == 0 || sourceId > SAFECSV_MAX_NODE_ID) return false;
        if (destinationId > SAFECSV_MAX_NODE_ID) return false;
        if (safeCsvIsReservedChar(type)) return false;

        char body[SAFECSV_MAX_FRAME_LEN];
        int written = snprintf(
            body,
            sizeof(body),
            "%u,%u,%u,%c,%u,%llu,%u,%u",
            (unsigned)version,
            (unsigned)sourceId,
            (unsigned)destinationId,
            type,
            (unsigned)sequence,
            (unsigned long long)timestamp,
            (unsigned)ttl,
            (unsigned)fieldCount
        );
        if (written <= 0 || (size_t)written >= sizeof(body)) return false;

        size_t pos = (size_t)written;
        for (uint8_t i = 0; i < fieldCount; ++i) {
            int n = snprintf(
                body + pos,
                sizeof(body) - pos,
                ",%s=%s",
                fields[i].key,
                fields[i].value
            );
            if (n <= 0 || pos + (size_t)n >= sizeof(body)) return false;
            pos += (size_t)n;
        }

        uint16_t crc = safeCsvCrc16CcittFalse(body, pos);
        int total = snprintf(outBuf, outBufSize, "<%s*%04X>", body, (unsigned)crc);
        if (total <= 0 || (size_t)total >= outBufSize || (size_t)total > SAFECSV_MAX_FRAME_LEN) {
            return false;
        }
        outLen = (size_t)total;
        return true;
    }

    bool decodeBody(const char* body, size_t bodyLen) {
        clear();
        if (!body || bodyLen == 0 || bodyLen >= SAFECSV_MAX_FRAME_LEN) return false;

        char scratch[SAFECSV_MAX_FRAME_LEN];
        memcpy(scratch, body, bodyLen);
        scratch[bodyLen] = '\\0';

        char* savePtr = nullptr;
        char* tok = strtok_r(scratch, ",", &savePtr);
        if (!tok) return false;
        version = (uint8_t)strtoul(tok, nullptr, 10);

        tok = strtok_r(nullptr, ",", &savePtr);
        if (!tok) return false;
        sourceId = (uint8_t)strtoul(tok, nullptr, 10);

        tok = strtok_r(nullptr, ",", &savePtr);
        if (!tok) return false;
        destinationId = (uint8_t)strtoul(tok, nullptr, 10);

        tok = strtok_r(nullptr, ",", &savePtr);
        if (!tok || strlen(tok) != 1) return false;
        type = tok[0];

        tok = strtok_r(nullptr, ",", &savePtr);
        if (!tok) return false;
        sequence = (uint16_t)strtoul(tok, nullptr, 10);

        tok = strtok_r(nullptr, ",", &savePtr);
        if (!tok) return false;
        timestamp = (uint64_t)strtoull(tok, nullptr, 10);

        tok = strtok_r(nullptr, ",", &savePtr);
        if (!tok) return false;
        ttl = (uint8_t)strtoul(tok, nullptr, 10);

        tok = strtok_r(nullptr, ",", &savePtr);
        if (!tok) return false;
        uint32_t declaredCount = (uint32_t)strtoul(tok, nullptr, 10);

        if (sourceId == 0 || sourceId > SAFECSV_MAX_NODE_ID || destinationId > SAFECSV_MAX_NODE_ID) {
            return false;
        }
        if (declaredCount > SAFECSV_MAX_FIELDS) return false;

        uint8_t actual = 0;
        while ((tok = strtok_r(nullptr, ",", &savePtr)) != nullptr) {
            char* eq = strchr(tok, '=');
            if (!eq || eq == tok) return false;
            *eq = '\\0';
            const char* k = tok;
            const char* v = eq + 1;
            if (!addField(k, v)) return false;
            actual++;
        }

        return actual == (uint8_t)declaredCount;
    }
};

/* ============================================================================
 * Node Identity & Reboot Session Tracking
 * ============================================================================ */
class SafeCsvNodeIdentity {
public:
    explicit SafeCsvNodeIdentity(uint8_t nodeId)
        : _nodeId(nodeId), _nextSeq(1), _sessionId((uint32_t)esp_random()) {
        _mutex = xSemaphoreCreateMutex();
    }

    uint8_t nodeId() const { return _nodeId; }
    uint32_t sessionId() const { return _sessionId; }

    uint16_t nextSequence() {
        uint16_t seq = 0;
        if (_mutex && xSemaphoreTake(_mutex, portMAX_DELAY) == pdTRUE) {
            seq = _nextSeq;
            _nextSeq = (uint16_t)(_nextSeq + 1); /* 16-bit rollover */
            xSemaphoreGive(_mutex);
        }
        return seq;
    }

    void stampPacket(SafeCsvPacket& pkt, bool embedSessionField = true) {
        pkt.version  = SAFECSV_PROTOCOL_VERSION;
        pkt.sourceId = _nodeId;
        pkt.sequence = nextSequence();
        if (embedSessionField) {
            char sidBuf[9];
            snprintf(sidBuf, sizeof(sidBuf), "%08lX", (unsigned long)_sessionId);
            pkt.addField("SID", sidBuf);
        }
    }

private:
    uint8_t           _nodeId;
    uint16_t          _nextSeq;
    uint32_t          _sessionId;
    SemaphoreHandle_t _mutex;
};

/* ============================================================================
 * 32-Packet Sliding Replay Window + Session Reboot Detection
 * ============================================================================ */
class SafeCsvSequenceTracker {
public:
    SafeCsvSequenceTracker() {
        _mutex = xSemaphoreCreateMutex();
        memset(_nodes, 0, sizeof(_nodes));
    }

    bool acceptPacket(const SafeCsvPacket& pkt) {
        if (pkt.sourceId == 0 || pkt.sourceId > SAFECSV_MAX_NODE_ID) return false;
        bool accepted = false;

        if (_mutex && xSemaphoreTake(_mutex, portMAX_DELAY) == pdTRUE) {
            NodeWindow& w = _nodes[pkt.sourceId];
            uint32_t pktSession = 0;
            bool hasSession = false;
            const char* sidStr = pkt.getString("SID");
            if (sidStr) {
                pktSession = (uint32_t)strtoul(sidStr, nullptr, 16);
                hasSession = true;
            }

            if (!w.initialized || (hasSession && w.hasSession && pktSession != w.sessionId)) {
                w.initialized = true;
                w.lastSeq     = pkt.sequence;
                w.bitmap      = 1UL;
                w.hasSession  = hasSession;
                w.sessionId   = pktSession;
                accepted      = true;
            } else {
                uint16_t fwd = (uint16_t)(pkt.sequence - w.lastSeq);
                if (fwd == 0) {
                    accepted = false; /* Duplicate of lastSeq */
                } else if (fwd < 0x8000) {
                    w.bitmap  = (fwd >= 32) ? 1UL : ((w.bitmap << fwd) | 1UL);
                    w.lastSeq = pkt.sequence;
                    accepted  = true;
                } else {
                    uint16_t back = (uint16_t)(w.lastSeq - pkt.sequence);
                    if (back < 32 && ((w.bitmap & (1UL << back)) == 0)) {
                        w.bitmap |= (1UL << back);
                        accepted = true;
                    }
                }
            }
            xSemaphoreGive(_mutex);
        }
        return accepted;
    }

private:
    struct NodeWindow {
        bool     initialized;
        uint16_t lastSeq;
        uint32_t bitmap;
        bool     hasSession;
        uint32_t sessionId;
    };

    NodeWindow        _nodes[SAFECSV_MAX_NODE_ID + 1];
    SemaphoreHandle_t _mutex;
};

/* ============================================================================
 * FreeRTOS Thread-Safe UART Link (One RX task + One TX task per UART)
 * ============================================================================ */
class SafeCsvLink {
public:
    SafeCsvLink(HardwareSerial& serial,
                SafeCsvNodeIdentity& identity,
                SafeCsvSequenceTracker& tracker)
        : _serial(serial),
          _identity(identity),
          _tracker(tracker),
          _rxLen(0),
          _inFrame(false),
          _frameStartMs(0) {
        _txQueue = xQueueCreate(SAFECSV_TX_QUEUE_DEPTH, sizeof(TxFrame));
    }

    /* Stamp with local NodeIdentity + Session and enqueue for TX */
    bool queueSendStamped(SafeCsvPacket& pkt, bool embedSessionField = true) {
        _identity.stampPacket(pkt, embedSessionField);
        return enqueueEncoded(pkt);
    }

    /* Replicate an already-stamped packet onto a second UART link (same SEQ & SID) */
    bool queueReplicate(const SafeCsvPacket& stampedPkt) {
        return enqueueEncoded(stampedPkt);
    }

    /* Forward a received packet preserving source, sequence, and session; decrement TTL */
    bool queueForward(const SafeCsvPacket& receivedPkt) {
        if (receivedPkt.ttl == 0) return false;
        SafeCsvPacket fwd = receivedPkt;
        fwd.ttl = (uint8_t)(receivedPkt.ttl - 1);
        return enqueueEncoded(fwd);
    }

    /* Call continuously from dedicated UART TX FreeRTOS task */
    void processTx() {
        if (!_txQueue) return;
        TxFrame item;
        if (xQueueReceive(_txQueue, &item, pdMS_TO_TICKS(10)) == pdTRUE) {
            _serial.write((const uint8_t*)item.data, item.len);
            _serial.flush();
        }
    }

    /* Call continuously from dedicated UART RX FreeRTOS task */
    bool pollReceive(SafeCsvPacket& outPkt) {
        /* Timeout protection if frame stalls mid-stream */
        if (_inFrame && (millis() - _frameStartMs > SAFECSV_FRAME_TIMEOUT_MS)) {
            _inFrame = false;
            _rxLen   = 0;
        }

        while (_serial.available() > 0) {
            int raw = _serial.read();
            if (raw < 0) break;
            char c = (char)raw;

            if (c == '<') {
                /* Resynchronize on new start delimiter */
                _inFrame      = true;
                _rxLen        = 0;
                _frameStartMs = millis();
                continue;
            }

            if (!_inFrame) continue;

            if (c == '>') {
                _inFrame = false;
                _rxBuf[_rxLen] = '\\0';
                bool valid = parseInnerFrame(_rxBuf, _rxLen, outPkt);
                _rxLen = 0;
                if (valid && _tracker.acceptPacket(outPkt)) {
                    return true;
                }
                continue;
            }

            if (_rxLen + 1 >= SAFECSV_MAX_FRAME_LEN) {
                /* Overflow protection */
                _inFrame = false;
                _rxLen   = 0;
                continue;
            }
            _rxBuf[_rxLen++] = c;
        }
        return false;
    }

private:
    struct TxFrame {
        size_t len;
        char   data[SAFECSV_MAX_FRAME_LEN + 1];
    };

    bool enqueueEncoded(const SafeCsvPacket& pkt) {
        if (!_txQueue) return false;
        TxFrame frame;
        if (!pkt.encodeFrame(frame.data, sizeof(frame.data), frame.len)) {
            return false;
        }
        return xQueueSend(_txQueue, &frame, 0) == pdTRUE;
    }

    bool parseInnerFrame(const char* inner, size_t len, SafeCsvPacket& outPkt) {
        const char* star = strrchr(inner, '*');
        if (!star || star == inner) return false;

        size_t bodyLen = (size_t)(star - inner);
        const char* crcStr = star + 1;
        if (strlen(crcStr) != 4) return false;

        uint16_t rxCrc  = (uint16_t)strtoul(crcStr, nullptr, 16);
        uint16_t expCrc = safeCsvCrc16CcittFalse(inner, bodyLen);
        if (rxCrc != expCrc) return false;

        return outPkt.decodeBody(inner, bodyLen);
    }

    HardwareSerial&         _serial;
    SafeCsvNodeIdentity&    _identity;
    SafeCsvSequenceTracker& _tracker;
    QueueHandle_t           _txQueue;
    char                    _rxBuf[SAFECSV_MAX_FRAME_LEN];
    size_t                  _rxLen;
    bool                    _inFrame;
    unsigned long           _frameStartMs;
};

#endif // CSV_PROTOCOL_H
`;
}

export function generateThreeEsp32Example(): string {
  return `#include "CsvProtocol.h"

/* Primary ESP32 dual-UART setup sharing NodeIdentity & SequenceTracker */
SafeCsvNodeIdentity    nodeIdentity(SAFECSV_NODE_PRIMARY);
SafeCsvSequenceTracker replayTracker;

SafeCsvLink toSecondary(Serial1, nodeIdentity, replayTracker);
SafeCsvLink toThird(Serial2, nodeIdentity, replayTracker);

QueueHandle_t appRxQueue = nullptr;

void rxTaskLink1(void* pv) {
    SafeCsvPacket pkt;
    for (;;) {
        if (toSecondary.pollReceive(pkt)) {
            xQueueSend(appRxQueue, &pkt, 0);
        }
        vTaskDelay(pdMS_TO_TICKS(2));
    }
}

void txTaskLink1(void* pv) {
    for (;;) {
        toSecondary.processTx();
    }
}

void txTaskLink2(void* pv) {
    for (;;) {
        toThird.processTx();
    }
}

void appTask(void* pv) {
    SafeCsvPacket rxPkt;
    for (;;) {
        if (xQueueReceive(appRxQueue, &rxPkt, pdMS_TO_TICKS(100)) == pdTRUE) {
            float humidity = 0.0f;
            if (rxPkt.getFloat("HUM", humidity)) {
                /* Use humidity; unknown fields are preserved without rejection */
            }
            /* Relay packet to Third ESP32 with TTL decremented */
            if (rxPkt.destinationId == SAFECSV_NODE_ALL || rxPkt.destinationId == SAFECSV_NODE_THIRD) {
                toThird.queueForward(rxPkt);
            }
        }
    }
}

void broadcastSensors() {
    SafeCsvPacket packet;
    packet.destinationId = SAFECSV_NODE_ALL;
    packet.type          = SAFECSV_TYPE_STATUS;
    packet.timestamp     = 1732183000ULL;

    packet.addField("CO2", "480");
    packet.addField("HUM", "65.5");
    packet.addField("TEMP", "24.2");
    packet.addField("PRESS", "1013.2");
    packet.addField("S7.CO2", "510");
    packet.addField("S7.TS", "1732183004");
    packet.addField("DOOR", "1");

    /* Stamp once on link 1, then replicate exact SEQ & SID to link 2 */
    if (toSecondary.queueSendStamped(packet)) {
        toThird.queueReplicate(packet);
    }
}`;
}

function escapeCppStr(input: string): string {
  return input.replace(/\\/g, '\\\\').replace(/"/g, '\\"');
}

export function generateInoSnippet(packet: SafeCsvPacket, limits: ProtocolLimits): string {
  const encoded = encodeFrame(packet, limits);
  const typeMacro =
    packet.type === 'S'
      ? 'SAFECSV_TYPE_STATUS'
      : packet.type === 'C'
      ? 'SAFECSV_TYPE_CONTROL'
      : packet.type === 'A'
      ? 'SAFECSV_TYPE_ACK'
      : packet.type === 'H'
      ? 'SAFECSV_TYPE_HEARTBEAT'
      : `'${packet.type}'`;

  const destExpr = packet.dest === 0 ? 'SAFECSV_NODE_ALL' : String(packet.dest);

  const addFieldLines =
    packet.fields.length > 0
      ? packet.fields
          .map((f) => `    packet.addField("${escapeCppStr(f.key)}", "${escapeCppStr(f.value)}");`)
          .join('\n')
      : '    // No payload fields configured';

  const rxExtractLines =
    packet.fields.length > 0
      ? packet.fields
          .map((f, idx) => {
            const safeVar = `val_${idx}`;
            const k = escapeCppStr(f.key);
            if (/^-?\d+$/.test(f.value.trim())) {
              return `            int32_t ${safeVar} = 0;\n            if (rx.getInt("${k}", ${safeVar})) { /* ${k} */ }`;
            }
            if (/^-?\d+(\.\d+)?$/.test(f.value.trim())) {
              return `            float ${safeVar} = 0.0f;\n            if (rx.getFloat("${k}", ${safeVar})) { /* ${k} */ }`;
            }
            return `            const char* ${safeVar} = rx.getString("${k}");\n            if (${safeVar} != nullptr) { /* ${k} */ }`;
          })
          .join('\n')
      : '            // Inspect rx.fieldCount and rx.fields[]';

  return `/* ============================================================================
 * SafeCsv ESP32 Sketch (.ino)
 * Generated wire preview (${encoded.byteLength} B): ${encoded.frame}
 * ============================================================================ */

#define SAFECSV_MAX_FIELDS       ${limits.maxFields}
#define SAFECSV_MAX_KEY_LEN      ${limits.maxKeyLen}
#define SAFECSV_MAX_VAL_LEN      ${limits.maxValLen}
#define SAFECSV_MAX_FRAME_LEN    ${limits.maxFrameLen}
#define SAFECSV_TX_QUEUE_DEPTH   ${limits.txQueueDepth}
#define SAFECSV_FRAME_TIMEOUT_MS ${limits.frameTimeoutMs}UL
#define SAFECSV_MAX_NODE_ID      ${limits.maxNodeId}

#include "CsvProtocol.h"

static const int UART1_RX_PIN = 16;
static const int UART1_TX_PIN = 17;
static const uint32_t UART_BAUD = 115200;

SafeCsvNodeIdentity    nodeIdentity(${packet.src});
SafeCsvSequenceTracker replayTracker;
SafeCsvLink            uartLink(Serial1, nodeIdentity, replayTracker);
QueueHandle_t          appRxQueue = nullptr;

void uartRxTask(void* pv) {
    SafeCsvPacket rxPkt;
    for (;;) {
        if (uartLink.pollReceive(rxPkt)) {
            xQueueSend(appRxQueue, &rxPkt, 0);
        }
        vTaskDelay(pdMS_TO_TICKS(2));
    }
}

void uartTxTask(void* pv) {
    for (;;) {
        uartLink.processTx();
    }
}

void sendConfiguredFrame() {
    SafeCsvPacket packet;
    packet.version       = ${packet.version};
    packet.destinationId = ${destExpr};
    packet.type          = ${typeMacro};
    packet.timestamp     = ${packet.ts || '0'}ULL;
    packet.ttl           = ${packet.ttl};

${addFieldLines}

    /* Stamps SRC=${packet.src}, next 16-bit SEQ, optional SID, computes CRC-16/CCITT-FALSE, and enqueues */
    uartLink.queueSendStamped(packet, false);
}

void setup() {
    Serial.begin(115200);
    Serial1.begin(UART_BAUD, SERIAL_8N1, UART1_RX_PIN, UART1_TX_PIN);
    appRxQueue = xQueueCreate(8, sizeof(SafeCsvPacket));

    xTaskCreatePinnedToCore(uartRxTask, "csv_rx", 4096, nullptr, 2, nullptr, 1);
    xTaskCreatePinnedToCore(uartTxTask, "csv_tx", 4096, nullptr, 2, nullptr, 1);
}

void loop() {
    SafeCsvPacket rx;
    if (xQueueReceive(appRxQueue, &rx, pdMS_TO_TICKS(50)) == pdTRUE) {
${rxExtractLines}

        if (rx.ttl > 0 && (rx.destinationId == SAFECSV_NODE_ALL || rx.destinationId != nodeIdentity.nodeId())) {
            uartLink.queueForward(rx);
        }
    }

    static unsigned long lastTxMs = 0;
    if (millis() - lastTxMs >= 5000UL) {
        lastTxMs = millis();
        sendConfiguredFrame();
    }
}`;
}

export function generateFrameCreationRulesForLlm(
  packet: SafeCsvPacket,
  limits: ProtocolLimits
): string {
  const encoded = encodeFrame(packet, limits);
  const fieldList =
    packet.fields.length > 0
      ? packet.fields.map((f) => `- ${f.key}=${f.value}`).join('\n')
      : '- (none)';

  return `ESP32 SafeCsv (CsvProtocol.h) Frame-Creation Rules & LLM Prompt Contract

1. WIRE GRAMMAR (STRICT)
   <VERSION,SRC,DEST,TYPE,SEQ,TS,TTL,COUNT,KEY1=VAL1,KEY2=VAL2,...*CRC16>
   - Start delimiter: '<'   |   End delimiter: '>'
   - Field separator: ','   |   Key/Value separator: '='   |   CRC prefix: '*'
   - Never use ',', '=', '*', '<', '>', '\\r', or '\\n' inside TYPE, keys, or values.

2. FIXED HEADER (8 POSITIONS, ALWAYS IN ORDER)
   [0] VERSION : uint8  (1..255, protocol version)
   [1] SRC     : uint8  (1..${limits.maxNodeId}, sender ESP32 node ID)
   [2] DEST    : uint8  (0 = SAFECSV_NODE_ALL broadcast, or 1..${limits.maxNodeId})
   [3] TYPE    : char   ('S'=Status, 'C'=Control, 'A'=Ack, 'H'=Heartbeat)
   [4] SEQ     : uint16 (0..65535, 16-bit rollover counter)
   [5] TS      : uint64 (packet timestamp, e.g. Unix epoch seconds)
   [6] TTL     : uint8  (forwarding hop limit; decremented by queueForward(), drop at 0)
   [7] COUNT   : uint8  (exact count of KEY=VALUE payload pairs; 0..${limits.maxFields})

3. VARIABLE PAYLOAD & INTEGRITY RULES
   - Every field after COUNT is a named KEY=VALUE pair (supports namespaced IDs like S7.CO2, S7.TS).
   - Unknown keys must NOT cause packet rejection; receivers read only keys they understand via getFloat()/getInt()/getString().
   - CRC16 = CRC-16/CCITT-FALSE (poly 0x1021, init 0xFFFF, no reflection, no final XOR) computed over the exact ASCII bytes strictly between '<' and '*', formatted as 4 uppercase hex digits (*XXXX).

4. ACTIVE COMPILE-TIME LIMITS (MUST MATCH ACROSS ALL ESP32 BOARDS)
   - SAFECSV_MAX_FIELDS       = ${limits.maxFields}
   - SAFECSV_MAX_KEY_LEN      = ${limits.maxKeyLen} chars
   - SAFECSV_MAX_VAL_LEN      = ${limits.maxValLen} chars
   - SAFECSV_MAX_FRAME_LEN    = ${limits.maxFrameLen} bytes (including <, *, CRC16, >)
   - SAFECSV_TX_QUEUE_DEPTH   = ${limits.txQueueDepth} frames
   - SAFECSV_FRAME_TIMEOUT_MS = ${limits.frameTimeoutMs} ms
   - SAFECSV_MAX_NODE_ID      = ${limits.maxNodeId}

5. FREERTOS & ROUTING API RULES FOR .INO CODE
   - Share one SafeCsvNodeIdentity and one SafeCsvSequenceTracker across UART links on the same ESP32.
   - Dedicate 1 RX FreeRTOS task (pollReceive()) and 1 TX FreeRTOS task (processTx()) per HardwareSerial link.
   - Use queueSendStamped() once for local packets, queueReplicate() to mirror the same SEQ/SID to another UART, and queueForward() to relay received packets (preserves SRC/SEQ/SID, decrements TTL).

6. CURRENT DESIGNED PACKET EXAMPLE
   Fields:
${fieldList}
   Encoded Wire Frame (${encoded.byteLength} / ${limits.maxFrameLen} bytes):
   ${encoded.frame}`;
}

